<?php use Solitude\Theme;$data=Theme::dataset('links');$all=[];foreach($data['links'] as $g)$all=array_merge($all,$g['link_list']); ?>
<?php if($all):?><div class="flink tw:[div&]:flex tw:[div&]:flex-col tw:[div&]:overflow-hidden tw:[div&]:relative" id="banners"><div class="banners-title"><div class="banners-title-small"><?=Theme::e(Theme::field($archive,'description',''))?></div><div class="banners-title-big"><?=Theme::e($archive->title)?></div></div><div class="banner-button-group"><button class="banner-button secondary" type="button" data-solitude-action="travelling"><i class="solitude fas fa-tower-broadcast"></i><span class="banner-button-text"><?=Theme::e(Theme::t('randomLink'))?></span></button><a class="banner-button" href="<?=Theme::get('comment.use')&&$archive->allowComment?'#post-comment':'#friend-links-apply'?>"><i class="solitude fas fa-circle-chevron-right"></i><span class="banner-button-text"><?=Theme::e(Theme::t('applyFriendLink'))?></span></a></div><div class="tags-group-all nowrapMove"><div class="tags-group-wrapper"><?php for($i=0;$i<max(24,count($all)*2);$i+=2):?><div class="tags-group-icon-pair"><?php for($j=0;$j<2;$j++):$item=$all[($i+$j)%count($all)];?><a class="tags-group-icon" href="<?=Theme::e(Theme::url($item['link']))?>" target="_blank" rel="noopener noreferrer" title="<?=Theme::e($item['name'])?>"><img class="no-lightbox" src="<?=Theme::e(Theme::media($item['avatar']??'/img/default_avatar.avif'))?>" alt=""><span class="tags-group-title"><?=Theme::e($item['name'])?></span></a><?php endfor;?></div><?php endfor;?></div></div></div><?php endif;?>
<div class="flink article-container" id="friend-links-list"><?php foreach($data['links'] as $group):?><h2><?=Theme::e($group['class_name']??'')?> (<?=count($group['link_list'])?>)</h2><div class="flink-desc"><?=Theme::e($group['class_desc']??'')?></div><div class="<?=($group['type']??'item')==='card'?'site-card-group':'flink-list'?>"><?php foreach($group['link_list'] as $item):?>
<?php if(($group['type']??'item')==='card'):?><div class="site-card"><?php if(isset($item['tag'])):?><span class="site-card-tag"><?=Theme::e($item['tag'])?></span><?php endif;?><a class="img" href="<?=Theme::e(Theme::url($item['link']))?>" target="_blank" rel="noopener noreferrer"><img class="flink-avatar no-lightbox" src="<?=Theme::e(Theme::media($item['topimg']??$item['avatar']??''))?>" alt="<?=Theme::e($item['name'])?>" loading="lazy"></a><a class="info cf-friends-link" href="<?=Theme::e(Theme::url($item['link']))?>" target="_blank" rel="noopener noreferrer"><div class="site-card-avatar"><img class="flink-avatar cf-friends-avatar no-lightbox" src="<?=Theme::e(Theme::media($item['avatar']??''))?>" alt=""><div class="img-alt is-center"><?=Theme::e($item['name'])?></div></div><div class="site-card-text"><span class="title cf-friends-name"><?=Theme::e($item['name'])?></span><span class="desc"><?=Theme::e($item['descr']??$item['description']??'')?></span></div></a></div>
<?php else:?><div class="flink-list-item"><a class="cf-friends-link" href="<?=Theme::e(Theme::url($item['link']))?>" target="_blank" rel="noopener noreferrer"><img class="flink-avatar cf-friends-avatar no-lightbox" src="<?=Theme::e(Theme::media($item['avatar']??'/img/default_avatar.avif'))?>" alt="" loading="lazy"><div class="flink-item-info"><span class="flink-item-name cf-friends-name"><?=Theme::e($item['name'])?></span><span class="flink-item-desc"><?=Theme::e($item['descr']??$item['description']??'')?></span></div></a></div><?php endif;?>
<?php endforeach;?></div><?php endforeach;?><div id="friend-links-apply"><?=$html?></div></div>
